for c,g in panels.items():
    coords={(r,k) for r,row in enumerate(g) for k,v in enumerate(row) if v}
    print(c, sorted(coords), 'output-colored',sum(out[r][k]==c for r,k in coords),'masked-by-other-output',sum(out[r][k] not in (0,c) for r,k in coords))
